// src/pages/admin/AddOrgPage.jsx
import { useMemo, useState } from "react";
import { useAuth } from "../../context/AuthContext";
import { useToast } from "../../context/ToastContext";
import PageHeader from "../../components/shared/PageHeader";
import DataTable from "../../components/shared/DataTable";
import Badge from "../../components/shared/Badge";
import { donorApi, bankApi, ngoApi, fundApi } from "../../services/api";

const EMPTY_FORM = { name: "", type: "NGO", desc: "", email: "", msp: "" };

const buildStatusType = (status) => {
  if (status === "Pass") return "green";
  if (status === "Fail") return "red";
  return "blue";
};

export default function AddOrgPage() {
  const { user } = useAuth();
  const toast = useToast();
  const [form, setForm] = useState(EMPTY_FORM);
  const [checksLoading, setChecksLoading] = useState(false);
  const [checks, setChecks] = useState([
    { check: "Donor Registry", status: "Not Run", details: "Run preflight to verify" },
    { check: "Bank Registry", status: "Not Run", details: "Run preflight to verify" },
    { check: "NGO Registry", status: "Not Run", details: "Run preflight to verify" },
    { check: "Funds Ledger", status: "Not Run", details: "Run preflight to verify" },
  ]);
  const [drafts, setDrafts] = useState([]);

  const userCert = user?.userCert || "admin";

  const upd = (k) => (e) => setForm((p) => ({ ...p, [k]: e.target.value }));

  const runPreflightChecks = async () => {
    setChecksLoading(true);
    const labels = ["Donor Registry", "Bank Registry", "NGO Registry", "Funds Ledger"];

    try {
      const results = await Promise.allSettled([
        donorApi.getAll({ userCert }),
        bankApi.getAll({ userCert }),
        ngoApi.getAll({ userCert }),
        fundApi.getAll({ userCert }),
      ]);

      const nextChecks = results.map((result, index) => {
        if (result.status === "fulfilled") {
          const count = Array.isArray(result.value?.data) ? result.value.data.length : 0;
          return { check: labels[index], status: "Pass", details: `${count} record(s) readable` };
        }
        return { check: labels[index], status: "Fail", details: result.reason?.message || "Request failed" };
      });

      setChecks(nextChecks);

      if (nextChecks.every((item) => item.status === "Pass")) {
        toast("Platform preflight checks passed", "success");
      } else {
        toast("Some checks failed. Review details before onboarding.", "error");
      }
    } catch (error) {
      toast(error?.message || "Failed to run preflight checks", "error");
    } finally {
      setChecksLoading(false);
    }
  };

  const submitDraft = () => {
    if (!form.name || !form.msp || !form.email) {
      toast("Name, MSP ID and admin email are required", "error");
      return;
    }

    if (!/^[A-Za-z0-9]+MSP$/.test(form.msp)) {
      toast("MSP ID format invalid. Example: Org4MSP", "error");
      return;
    }

    const draft = {
      id: `REQ-${Date.now()}`,
      name: form.name,
      type: form.type,
      msp: form.msp,
      email: form.email,
      status: "Draft",
      createdAt: new Date().toLocaleString(),
    };

    setDrafts((prev) => [draft, ...prev].slice(0, 20));
    toast("Onboarding draft saved. Network join still requires backend Fabric scripts.", "success");
    setForm(EMPTY_FORM);
  };

  const checklist = useMemo(() => {
    const safeMsp = form.msp || "OrgXMSP";
    const safeName = form.name || "new-org";
    return [
      `1. Generate crypto material for ${safeMsp}`,
      `2. Add org definitions to fabric-samples/test-network configuration`,
      `3. Bring up peer + CA for ${safeName}`,
      `4. Join the new peer to channel and approve chaincode definitions`,
      `5. Enroll org admin and import wallet identity for runtime access`,
    ];
  }, [form.msp, form.name]);

  return (
    <div>
      <PageHeader title="Platform Admin Control" desc="Run ledger preflight checks and prepare organization onboarding requests" />
      <div className="grid-2">
        <div className="card">
          <div className="form-grid section-gap">
            <div className="form-group">
              <label>Platform User Cert</label>
              <input value={userCert} disabled />
              <span className="input-hint">Loaded from active session</span>
            </div>
            <div className="form-group">
              <label>Organization Name</label>
              <input value={form.name} onChange={upd("name")} placeholder="e.g. GreenNGOMSP" />
            </div>
            <div className="form-group">
              <label>Type</label>
              <select value={form.type} onChange={upd("type")}>
                <option value="NGO">NGO</option>
                <option value="Government">Government</option>
                <option value="Bank">Financial Institution</option>
                <option value="Other">Other</option>
              </select>
            </div>
            <div className="form-group">
              <label>Network MSP ID</label>
              <input value={form.msp} onChange={upd("msp")} placeholder="e.g. Org4MSP" />
              <span className="input-hint">Format: Alphanumeric ending with MSP</span>
            </div>
            <div className="form-group">
              <label>Admin Email</label>
              <input value={form.email} onChange={upd("email")} type="email" placeholder="admin@org.com" />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea value={form.desc} onChange={upd("desc")} placeholder="Organization role and scope" />
            </div>
            <div className="form-actions">
              <button className="btn btn-secondary" onClick={() => setForm(EMPTY_FORM)}>Clear</button>
              <button className="btn btn-secondary" onClick={runPreflightChecks} disabled={checksLoading}>
                {checksLoading ? "Running Checks..." : "Run Preflight"}
              </button>
              <button className="btn btn-primary" onClick={submitDraft}>Save Onboarding Draft</button>
            </div>
          </div>
        </div>

        <div className="card">
          <div className="card-title" style={{ marginBottom: 10 }}>Preflight Status</div>
          <DataTable
            columns={[
              { key: "check", label: "Check" },
              { key: "status", label: "Status", render: (r) => <Badge type={buildStatusType(r.status)}>{r.status}</Badge> },
              { key: "details", label: "Details" },
            ]}
            data={checks}
            emptyText="No checks configured"
          />
        </div>
      </div>

      <div className="grid-2" style={{ marginTop: 14 }}>
        <div className="card">
          <div className="card-title" style={{ marginBottom: 10 }}>Onboarding Checklist</div>
          <div className="section-gap">
            {checklist.map((line) => (
              <div key={line} className="card-sub">{line}</div>
            ))}
          </div>
        </div>
        <div className="card">
          <div className="card-title" style={{ marginBottom: 10 }}>Draft Queue</div>
          <DataTable
            columns={[
              { key: "id", label: "Request ID", mono: true },
              { key: "name", label: "Name" },
              { key: "type", label: "Type" },
              { key: "msp", label: "MSP" },
              { key: "status", label: "Status", render: (r) => <Badge type="blue">{r.status}</Badge> },
              { key: "createdAt", label: "Created" },
            ]}
            data={drafts}
            emptyText="No onboarding drafts yet"
          />
        </div>
      </div>
    </div>
  );
}
